-- Smart scheduling: Admin-configurable session capacities and facility limits.
-- Additive only and safe to run again. No row is seeded: the API uses the defaults
-- (Orientation/Tasting 5 per session and 5 at the same time; Training 1 per session and 2 at the same time)
-- until Admin saves. Existing sessions are not changed.
create table if not exists public."schedule_settings" (
  "id" bigint generated by default as identity primary key,
  "orientation_capacity" smallint not null default 5,
  "training_capacity" smallint not null default 1,
  "orientation_facility_limit" smallint not null default 5,
  "training_facility_limit" smallint not null default 2,
  "updated_by_user_id" bigint references public."users" ("id") on delete set null,
  "created_at" timestamptz default now(),
  "updated_at" timestamptz default now(),
  constraint "schedule_settings_limits_check" check (
    "orientation_capacity" between 1 and 50 and "training_capacity" between 1 and 50
    and "orientation_facility_limit" between 1 and 50 and "training_facility_limit" between 1 and 50
  )
);
alter table public."schedule_settings" enable row level security;
create index if not exists "schedule_settings_updated_by_user_id_idx" on public."schedule_settings" ("updated_by_user_id");
